(async function () {
  'use strict';
  const C=window.Shelf, boot=JSON.parse(document.getElementById('boot-data').textContent);
  const EDIT=boot.role==='editor', $=id=>document.getElementById(id), root=$('app');
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icons={book:'M3 4h6c2 0 3 1 3 3v14c0-2-1-3-3-3H3z M21 4h-6c-2 0-3 1-3 3v14c0-2 1-3 3-3h6z',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',rank:'M4 20V10h4v10 M10 20V4h4v16 M16 20v-7h4v7',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4 M8 14h2 M14 14h2',tag:'M3 4h8l10 10-7 7L3 10z M7 7h.01',plus:'M12 5v14 M5 12h14',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',settings:'M9.5 3h5l.5 2.7 2.1 1.2 2.6-.9 2 3.5-2.1 1.8v2.4l2.1 1.8-2 3.5-2.6-.9-2.1 1.2-.5 2.7h-5L9 19.3l-2.1-1.2-2.6.9-2-3.5 2.1-1.8v-2.4L2.3 9.5l2-3.5 2.6.9L9 5.7z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',cloud:'M7 18H5a4 4 0 1 1 1-8 6 6 0 0 1 12-1 4.5 4.5 0 0 1 1 9h-2 M12 21V11 M8 15l4-4 4 4',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',heart:'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 0 9 8 15 8-6 12-11 8-15z',moon:'M20 15a8.5 8.5 0 0 1-11-11 9 9 0 1 0 11 11',close:'M5 5l14 14 M19 5L5 19',edit:'M15 4l5 5 M4 20l5-1L21 7l-4-4L5 15z',list:'M8 5h13 M8 12h13 M8 19h13 M3 5h.01 M3 12h.01 M3 19h.01',refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 12-1l2 3 M18 17a7 7 0 0 1-12 1l-2-3',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',arrow:'M5 12h14 M14 7l5 5-5 5',check:'M4 12l5 5L20 6',external:'M14 3h7v7 M21 3L10 14 M10 5H4v15h15v-6'};
  const ico=n=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.book}"/></svg>`;
  const btn=(act,text,cls='',extra='')=>`<button class="btn ${cls}" data-action="${act}" ${extra}>${text}</button>`;
  const dateFmt=s=>s&&!Number.isNaN(Date.parse(s))?new Date(s).toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'尚未发布';
  const state={payload:C.parsePayload(boot.seed||{items:[]}),view:'watching',filter:{media:'all',query:'',status:'',grade:'',tags:[],tagMode:'all',favorite:false},sort:'recent',layout:'grid',watch:'daily',rankGroup:false,dirty:false,locked:null,cache:false,notice:'',remoteSha:'',repoKey:'',busy:false};
  let db, storageFallback=false, password='',ghToken='',bgmToken='',config={},pending=[],pendingKind='',abortImport=null,toastTimer,undoState=null,modalFocus=null,viewLoadSeq=0;
  const settingKey='hhdShelfConfig_v4',legacyKey='animeWatchlistData_v1';
  const loadJSON=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))||f;}catch{return f;}};
  function setLocal(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{return false;}}
  async function openDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open('HHD-Workshelf-v4',1);q.onupgradeneeded=()=>q.result.createObjectStore('docs');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);q.onblocked=()=>reject(new Error('请关闭另一标签页后重试'));});}
  async function storeGet(k){if(storageFallback)return loadJSON('hhdShelf_'+k,null);return new Promise((res,rej)=>{const q=db.transaction('docs').objectStore('docs').get(k);q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error);});}
  async function storePut(k,v){if(storageFallback){if(!setLocal('hhdShelf_'+k,v))throw new Error('本机存储空间不足，请立即导出备份');return;}return new Promise((res,rej)=>{const t=db.transaction('docs','readwrite');t.objectStore('docs').put(v,k);t.oncomplete=res;t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error||new Error('保存中断'));});}
  async function persist(){if(!EDIT)return;await storePut('editor',{payload:state.payload,dirty:state.dirty,remoteSha:state.remoteSha,repoKey:state.repoKey});}
  function payload(){return {version:4,title:state.payload.title,publishedAt:state.payload.publishedAt,items:state.payload.items};}
  function toast(text,undo=false){clearTimeout(toastTimer);let el=$('toast');if(!el){el=document.createElement('div');el.id='toast';el.className='toast';el.setAttribute('role','status');document.body.append(el);}el.innerHTML=`<span>${esc(text)}</span>${undo?'<button data-action="undo">撤销</button>':''}`;toastTimer=setTimeout(()=>el.remove(),undo?10000:4500);}
  async function mutate(fn,message,undo=false){
    if(!EDIT)return;
    const before=JSON.parse(JSON.stringify(payload()));if(undo)await storePut('safety',before);fn();state.dirty=true;
    try{await persist();if(undo)undoState=before;render();if(message)toast(message,undo);}
    catch(e){state.notice='保存失败：'+e.message+'。请立即导出备份，当前修改仍在此页面。';render();toast(state.notice);throw e;}
  }
  function item(id){return state.payload.items.find(i=>i.id===id);}
  const statText=i=>({wish:i.media==='anime'?'想看':'待读',doing:i.media==='anime'?'在看':'在读',done:i.media==='anime'?'已看完':'已读完',hold:'搁置',dropped:'放弃'})[i.status];
  function progress(i){return `${i.current}${i.total!==''?' / '+i.total:''} ${i.unit}`;}
  function bar(i){return `<div class="progress-bar"><i style="width:${i.total?Math.min(100,i.current/i.total*100):0}%"></i></div>`;}
  function cover(i,cls=''){const url=C.safeURL(i.image,true);return url?`<img class="poster ${cls}" src="${esc(url)}" alt="${esc(i.title)}封面" loading="lazy" referrerpolicy="no-referrer" data-fallback-title="${esc(i.title)}" data-media="${i.media}">`:fallback(i);}
  function fallback(i){return `<div class="poster-fallback" data-media="${i.media}"><strong>${esc(i.title)}</strong><small>${C.mediaNames[i.media]} COLLECTION</small></div>`;}
  const tagsHTML=(i,n=3)=>[...new Set([...i.personalTags,...i.tags])].slice(0,n).map(t=>`<button class="tag" data-action="tag-filter" data-tag="${esc(t)}">${esc(t)}</button>`).join('');
  function empty(title,text,action=''){return `<div class="empty">${ico('book')}<h3>${title}</h3><p>${text}</p>${action}</div>`;}
  function card(i){return `<article class="work-card" data-work="${esc(i.id)}"><button class="poster-button" data-action="detail" data-id="${esc(i.id)}" aria-label="查看 ${esc(i.title)}"><div class="cover-wrap">${cover(i)}<span class="media-badge">${C.mediaNames[i.media]}</span>${i.favorite?`<span class="favorite">${ico('heart')}</span>`:''}<span class="score-badge ${i.score===null?'unrated':''}">${i.score===null?'待评分':i.score.toFixed(1)}</span></div></button><button class="title-button" data-action="detail" data-id="${esc(i.id)}"><h3>${esc(i.title)}</h3></button><div class="card-meta"><span><i class="status-dot"></i>${statText(i)}</span><span class="mono">${progress(i)}</span></div><div class="card-tags">${tagsHTML(i)}</div>${bar(i)}</article>`;}
  function listCard(i,watch=false){return `<article class="list-card" data-work="${esc(i.id)}"><button class="poster-button" data-action="detail" data-id="${esc(i.id)}">${cover(i)}</button><div class="grow"><button class="title-button" data-action="detail" data-id="${esc(i.id)}"><h3>${esc(i.title)}</h3></button><div class="small muted">${C.mediaNames[i.media]} · ${statText(i)} · ${progress(i)}</div>${watch?'':`<div class="card-tags">${tagsHTML(i,5)}</div>`}${bar(i)}${watch?`<div class="watch-actions"><span class="small muted">${i.score!==null?'我的评分 '+i.score.toFixed(1):'待评分'}</span>${EDIT?`<div class="row">${i.type==='daily'?btn('move-binge','转完结待看','tiny',`data-id="${esc(i.id)}" title="作品已播完，移到完结待看；保留观看进度"`):''}${btn('complete-work',i.media==='anime'?'已看完':'已读完','tiny',`data-id="${esc(i.id)}"`)}${btn('remove-watch','移出待看','tiny ghost',`data-id="${esc(i.id)}"`)}${btn('plus','＋1 '+i.unit,'tiny',`data-id="${esc(i.id)}" ${i.total!==''&&i.current>=i.total?'disabled':''}`)}</div>`:''}</div>`:''}</div>${watch?'':`<span class="big-score">${i.score!==null?i.score.toFixed(1):'—'}</span>`}</article>`;}
  function option(v,label,selected){return `<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(label)}</option>`;}
  function selectedTags(){return C.tags([...(state.filter.tags||[]),...(state.filter.tag?[state.filter.tag]:[])]);}
  function tagPicker(){
    const counts=new Map(),selected=selectedTags();
    state.payload.items.forEach(i=>[...new Set([...i.tags,...i.personalTags])].forEach(t=>counts.set(t,(counts.get(t)||0)+1)));
    const sorted=[...counts].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'zh-CN'));
    modal('筛选标签',`<p class="small muted">可同时勾选多个标签，并与名称、状态和评分筛选一起使用。</p><div class="tag-picker-tools mt"><input id="tag-search" placeholder="查找标签…" aria-label="查找标签"><select id="tag-match-mode" aria-label="标签匹配方式">${option('all','同时包含全部所选标签',state.filter.tagMode||'all')}${option('any','包含任意一个所选标签',state.filter.tagMode||'all')}</select></div><div class="tag-options mt">${sorted.map(([t,n])=>`<label class="tag-option" data-tag-text="${esc(t.toLocaleLowerCase())}"><input type="checkbox" class="tag-pick" value="${esc(t)}" aria-label="${esc(t)}" ${selected.includes(t)?'checked':''}><span>${esc(t)}</span><small>${n}</small></label>`).join('')||'<p class="small muted">还没有标签，编辑作品或从 Bangumi 导入后即可筛选。</p>'}</div>`,`${btn('reset-tag-picker','清空勾选')}${btn('apply-tags','应用筛选','primary')}`);
  }
  function filterHTML(){const f=state.filter,all=state.payload.items,selected=selectedTags();return `<div class="filter-panel"><div class="spread"><div class="type-tabs">${[['all','全部作品'],...Object.entries(C.mediaNames)].map(([k,v])=>`<button class="pill ${f.media===k?'active':''}" data-action="media" data-value="${k}">${v}<span class="count">${k==='all'?all.length:all.filter(x=>x.media===k).length}</span></button>`).join('')}</div><label class="check-label small muted"><input type="checkbox" id="favorite-only" ${f.favorite?'checked':''}>只看心头好</label></div><div class="filters"><select id="filter-status" aria-label="观看状态">${option('','全部状态',f.status)}${Object.entries(C.statuses).map(([k,v])=>option(k,v,f.status)).join('')}</select><select id="filter-grade" aria-label="评分分区">${[['','全部评分'],...C.gradeBands.map(b=>[b.id,b.label]),['unrated','待评分']].map(([k,v])=>option(k,v,f.grade)).join('')}</select><select id="filter-sort" aria-label="排序方式">${[['recent','最近更新'],['score','评分从高到低'],['title','作品名称'],['priority','观看优先级']].map(([k,v])=>option(k,v,state.sort)).join('')}</select><div class="search-with-tags"><div class="search">${ico('search')}<input id="search" value="${esc(f.query)}" placeholder="寻找作品、标签、评语…" aria-label="搜索作品"></div>${btn('tag-picker',ico('tag')+'筛选标签'+(selected.length?' ('+selected.length+')':''),selected.length?'selected-filter':'','aria-label="筛选标签"')}</div></div>${selected.length?`<div class="selected-tags"><span class="small muted">${f.tagMode==='any'?'包含任意标签':'同时包含'}：</span>${selected.map(t=>btn('remove-tag',esc(t)+' ×','tiny',`data-tag="${esc(t)}" aria-label="移除标签 ${esc(t)}"`)).join('')}${btn('clear-tags','清空','tiny ghost')}</div>`:''}</div>`;}

  function libraryHTML(){const data=C.sort(C.filter(state.payload.items,state.filter),state.sort);return `${filterHTML()}<div class="result-line"><span>${data.length} 部作品 · ${selectedTags().length?'已选 '+selectedTags().length+' 个标签':'每一个封面，都是一段记忆'}</span><div class="view-toggle"><button class="icon-btn ${state.layout==='grid'?'active':''}" data-action="layout" data-value="grid" aria-label="封面视图">${ico('grid')}</button><button class="icon-btn ${state.layout==='list'?'active':''}" data-action="layout" data-value="list" aria-label="列表视图">${ico('list')}</button></div></div><div class="${state.layout==='grid'?'shelf':'work-list'}">${data.length?data.map(i=>state.layout==='grid'?card(i):listCard(i)).join(''):empty('这一格，留给下一部好作品','可以调整筛选条件，或从 Bangumi 导入你喜欢的故事。',EDIT?btn('add',ico('plus')+'添加作品','primary'):'')}</div>`;}
  function rankingHTML(){const f={...state.filter};const data=C.sort(C.filter(state.payload.items,f).filter(i=>i.score!==null),'score');const row=(i,n)=>`<article class="rank-row"><span class="rank-n">${String(n+1).padStart(2,'0')}</span><button class="poster-button" data-action="detail" data-id="${esc(i.id)}">${cover(i)}</button><div><button class="title-button" data-action="detail" data-id="${esc(i.id)}"><h3>${esc(i.title)}</h3></button><div class="small muted">${C.mediaNames[i.media]} · ${statText(i)}${i.favorite?' · 心头好':''}</div><div class="card-tags">${tagsHTML(i,4)}</div></div><div class="rank-score"><strong>${i.score.toFixed(1)}</strong><small>我的评分</small></div></article>`;
    return `${filterHTML()}<div class="result-line"><span>${data.length} 部已评分 · 按个人评分排序，同分并列</span><label class="check-label"><input type="checkbox" id="rank-group" ${state.rankGroup?'checked':''}>按分区展示</label></div>${data.length?state.rankGroup?C.gradeBands.map(band=>{const a=data.filter(i=>C.grade(i)===band.id);return a.length?`<h2 class="grade-heading">${band.label} <small>${a.length} 部作品</small></h2>${a.map(i=>row(i,data.findIndex(x=>x.score===i.score))).join('')}`:'';}).join(''):data.map(i=>row(i,data.findIndex(x=>x.score===i.score))).join(''):empty('你的榜单，等你落下第一笔','点开作品封面，输入 9.9、9.8 或任何属于你的分数。未评分作品不会按 0 分参与排名。',btn('nav','返回作品库','primary','data-view="library"'))}`;
  }
  function watchingHTML(){const active=state.payload.items.filter(C.isWatching);const data=C.filter(active,state.filter).filter(i=>i.type===state.watch);const names={daily:'每日更新',binge:'完结待看',manga:'漫画待看',novel:'小说待看'};const today=C.weekdays[(new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Shanghai'})).getDay()+6)%7];
    const tiers=a=>C.priorities.map(t=>{const list=C.sort(a.filter(i=>i.priority===t),'recent');return list.length?`<div class="mt"><div class="tier-label"><span class="tier ${t}">${t}</span>${{SSR:'最优先',SR:'比较想看',R:'有空再看'}[t]} · ${list.length} 部</div><div class="watch-cards">${list.map(i=>listCard(i,true)).join('')}</div></div>`:'';}).join('');
    return `<div class="filter-panel"><div class="type-tabs">${Object.entries(names).map(([k,v])=>`<button class="pill ${state.watch===k?'active':''}" data-action="watch-tab" data-value="${k}">${v}<span class="count">${active.filter(i=>i.type===k).length}</span></button>`).join('')}</div><p class="small muted mt">已看完，或暂时不想追？点“已看完 / 已读完”或“移出待看”。作品、评分和评语仍保留在作品库。</p></div>${state.watch==='daily'?C.weekdays.map(d=>`<section class="watch-day"><div class="day-label ${d===today?'today':''}">${d}<small>${d===today?'TODAY · 今天':'每周更新'}</small></div><div>${tiers(data.filter(i=>i.weekday===d))||'<div class="small muted">这天暂时没有追更作品。</div>'}</div></section>`).join(''):tiers(data)||empty('这里暂时没有待看作品','在作品详情中点“加入待看”，或编辑资料选择“加入追番追更”。',EDIT?btn('add','添加作品','primary'):'')}`;
  }

  function render(){
    if(state.locked){renderLock();return;}
    const titles={library:['MY PERSONAL COLLECTION','收藏那些，值得记住的故事。','动画、漫画与小说，和只属于你的感想。'],ranking:['PERSONAL RANKING','好故事，自有你的分量。','每一个分数，都遵从自己的感受。'],watching:['WATCHING & READING','故事，还在继续。','把每一集、每一话的期待，慢慢记录下来。'],settings:['WORKSPACE SETTINGS','让收藏，跟着你走。','本地保存、GitHub 发布与数据备份。']};
    const t=titles[state.view],items=state.payload.items,scored=items.filter(i=>i.score!==null);
    root.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#watching" data-action="nav" data-view="watching"><span class="brand-mark"><img src="./icon.svg" alt="王之宝库图标" width="40" height="40"></span><span><strong>王之宝库</strong><small>HHD · WORKSHELF</small></span></a><div class="sidebar-label">我的收藏室</div><nav class="nav" aria-label="主导航">${[['watching','calendar','追番追更',''],['ranking','rank','个人榜单',scored.length],['library','grid','作品库',items.length]].map(([k,ic,label,n])=>`<button data-action="nav" data-view="${k}" class="${state.view===k?'active':''}">${ico(ic)}${label}<span class="num">${n}</span></button>`).join('')}</nav><div class="sidebar-bottom"><nav class="nav"><button data-action="nav" data-view="settings" class="${state.view==='settings'?'active':''}">${ico('settings')}设置与备份</button>${EDIT?`<button data-action="import">${ico('download')}导入作品</button>`:''}</nav><div class="side-note"><div class="row"><span class="avatar">H</span><span>${esc(state.payload.title)}</span></div><div style="margin-top:14px"><i class="status-dot ${state.dirty?'dirty':''}"></i>${EDIT?state.dirty?'本机有修改 · 待发布':'本机已保存':'作品库浏览模式'}</div><div>${navigator.onLine?'':'当前离线 · '}${state.payload.publishedAt?'发布于 '+dateFmt(state.payload.publishedAt):'留一页，给喜欢的故事。'}</div></div></div></aside><main class="workspace"><header class="topbar"><div class="breadcrumb">我的收藏室<span>/</span>${{library:'作品库',ranking:'个人榜单',watching:'追番追更',settings:'设置'}[state.view]}</div><div class="tools"><button class="icon-btn" data-action="theme" aria-label="切换明暗主题">${ico('moon')}</button><button class="icon-btn" data-action="nav" data-view="settings" aria-label="设置与备份">${ico('settings')}</button>${EDIT?`${btn('refresh',ico('refresh')+'刷新','',`title="读取 GitHub 最新作品库" aria-label="刷新作品库，读取 GitHub" ${state.busy?'disabled':''}`)}${btn('publish',ico('cloud')+'发布','',state.busy?'disabled':'')}${btn('add',ico('plus')+'添加作品','primary')}`:`${btn('refresh',ico('refresh')+'刷新')}${btn('open-editor',ico('edit')+'进入编辑','primary')}`}</div></header><section class="hero"><div><div class="eyebrow">${t[0]}</div><h1>${t[1]}</h1><p>${t[2]}</p></div>${state.view!=='settings'?`<div class="hero-stats"><div class="hero-stat"><strong>${String(items.length).padStart(2,'0')}</strong><small>部作品</small></div><div class="hero-stat"><strong>${scored.length}</strong><small>已评分</small></div><div class="hero-stat"><strong>${items.filter(i=>i.favorite).length}</strong><small>心头好</small></div></div>`:''}</section>${state.notice?`<div class="notice warn">${esc(state.notice)}</div>`:''}${state.view==='library'?libraryHTML():state.view==='ranking'?rankingHTML():state.view==='watching'?watchingHTML():settingsHTML()}<footer class="footer"><span>王之宝库 · HHD 的私人作品收藏　/　v4.1</span><span>${EDIT?(state.dirty?'修改已存本机，发布后其他设备可见。':'编辑模式 · 不会自动发布。'):(state.cache?'离线缓存 · 联网后可刷新':'浏览模式 · 个人评分与 Bangumi 均分独立')}</span></footer></main></div>`;
    document.title=state.payload.title==='王之宝库'?'王之宝库':state.payload.title+' · 王之宝库';
  }
  function modal(title,html,foot='',wide=false){let d=$('modal');if(d){d.remove();}else modalFocus=document.activeElement;d=document.createElement('dialog');d.id='modal';d.setAttribute('aria-label',title);if(wide)d.style.width='min(950px,calc(100% - 28px))';d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="关闭">${ico('close')}</button></div><div class="modal-body">${html}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;document.body.append(d);d.addEventListener('cancel',()=>{abortImport?.abort();});d.addEventListener('close',()=>{abortImport?.abort();d.remove();modalFocus?.focus?.();});d.showModal();return d;}
  function closeModal(){abortImport?.abort();$('modal')?.close();}
  function formError(e){const el=$('form-error');if(el){el.hidden=false;el.textContent=e.message||String(e);}else toast(e.message||String(e));}
  const errorBox=()=>'<div id="form-error" class="form-error" role="alert" hidden></div>';
  function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
  function openEditor(){if(location.protocol==='file:'){location.href=new URL('editor.html',location.href).href;}else{location.href=new URL('editor.html',location.href).href;}}
  function detail(id){const i=item(id);if(!i)return;
    const related=i.series?state.payload.items.filter(x=>x.id!==i.id&&x.series===i.series):[];
    modal('作品详情',`<div class="detail-layout"><div class="detail-poster">${cover(i)}${i.sourceUrl?`<a class="btn mt" href="${esc(i.sourceUrl)}" target="_blank" rel="noopener noreferrer">${ico('external')}来源条目</a>`:''}</div><div class="detail-main"><div class="row small muted">${C.mediaNames[i.media]}${i.year?' · '+esc(i.year):''} <span class="tier ${i.priority}">${i.priority}</span>${i.favorite?' ♥ 心头好':''}</div><h2>${esc(i.title)}</h2><div class="original">${esc(i.originalTitle)}</div><div class="row">${tagsHTML(i,30)}</div><div class="detail-score"><div><strong>${i.score===null?'—':i.score.toFixed(1)}</strong><small>我的评分</small></div><div><span class="mono">${i.bgmScore!==null?i.bgmScore.toFixed(1):'—'}</span><small>Bangumi 参考分</small></div>${EDIT?`<div class="score-edit"><input type="number" id="quick-score" min="0" max="10" step="0.1" value="${i.score??''}" placeholder="如 9.8" aria-label="我的评分">${btn('save-score','保存','tiny',`data-id="${esc(i.id)}"`)}</div>`:''}</div><div class="spread"><span class="small">${statText(i)} · <span class="mono">${progress(i)}</span></span>${EDIT?btn('plus','＋1 '+i.unit,'tiny',`data-id="${esc(i.id)}" data-detail="true" ${i.total!==''&&i.current>=i.total?'disabled':''}`):''}</div>${bar(i)}<p class="small muted mt">${C.isWatching(i)?'已加入追番追更':'仅存作品库 · 不在待看区'}</p>${EDIT?`<div class="row mt">${btn('edit',ico('edit')+'编辑资料','',`data-id="${esc(i.id)}"`)}${btn('favorite',ico('heart')+(i.favorite?'取消心头好':'标为心头好'),'',`data-id="${esc(i.id)}"`)}${C.isWatching(i)?`${btn('complete-work',i.media==='anime'?'标记已看完':'标记已读完','',`data-id="${esc(i.id)}" data-detail="true"`)}${btn('remove-watch','移出待看','',`data-id="${esc(i.id)}" data-detail="true"`)}`:!['done','dropped'].includes(i.status)?btn('add-watch','加入待看','',`data-id="${esc(i.id)}" data-detail="true"`):''}</div>`:''}</div></div>${i.summary?`<details class="detail-section"><summary class="small">作品简介</summary><div class="prose mt">${esc(i.summary)}</div></details>`:''}<section class="detail-section"><div class="spread"><h3>我的评价</h3>${EDIT?btn('edit-review','编辑长评','tiny',`data-id="${esc(i.id)}"`):''}</div><div class="prose ${i.review?'':'muted'}">${esc(i.review||'还没有写下评价。留一段话，给未来重温的自己。')}</div></section>${i.note?`<section class="detail-section"><h3>备注</h3><div class="prose muted">${esc(i.note)}</div></section>`:''}${related.length?`<section class="detail-section"><h3>同系列作品</h3><div class="row">${related.map(x=>btn('detail',esc(x.title),'tiny',`data-id="${esc(x.id)}"`)).join('')}</div></section>`:''}<section class="detail-section"><h3>随手记 <span class="muted small">${i.comments.length} 条</span></h3>${EDIT?`<form id="comment-form" data-id="${esc(i.id)}"><textarea name="text" required maxlength="20000" style="width:100%" placeholder="这一集的感想、喜欢的角色、重看时的新发现…" aria-label="添加感想"></textarea><div class="row" style="justify-content:flex-end;margin-top:8px"><button class="btn primary" type="submit">记下来</button></div></form>`:''}${[...i.comments].reverse().map(n=>`<article class="comment"><div class="spread"><time>${dateFmt(n.at)}</time>${EDIT?`<div>${btn('edit-comment','编辑','tiny ghost',`data-id="${esc(i.id)}" data-comment="${esc(n.id)}"`)}${btn('delete-comment','删除','tiny ghost',`data-id="${esc(i.id)}" data-comment="${esc(n.id)}"`)}</div>`:''}</div><div class="prose">${esc(n.text)}</div></article>`).join('')}${!i.comments.length&&!EDIT?'<p class="small muted">暂时没有随手记。</p>':''}</section>${i.scoreHistory.length>1?`<details class="detail-section"><summary class="small muted">评分足迹</summary><div class="small mt">${i.scoreHistory.slice(-20).reverse().map(h=>`<div>${h.score.toFixed(1)} <span class="muted">· ${dateFmt(h.at)}</span></div>`).join('')}</div></details>`:''}`,EDIT?btn('delete','删除作品','danger',`data-id="${esc(i.id)}"`):'');
  }
  function field(label,name,value='',attrs=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" value="${esc(value)}" ${attrs}></div>`;}
  function selectField(label,name,choices,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${choices.map(([k,v])=>option(k,v,value)).join('')}</select></div>`;}
  function editForm(id=''){
    if(!EDIT)return;const old=item(id),i=old||C.normalize({status:'wish',type:state.view==='watching'?state.watch:'binge',inWatchlist:state.view==='watching'});
    modal(old?'编辑作品':'添加一部作品',`<form id="work-form" data-id="${esc(id)}"><div class="form-grid">${field('作品名称 *','title',i.title==='未命名作品'?'':i.title,'required maxlength="300" placeholder="写下作品名称"')}${field('原名 / 别名','originalTitle',i.originalTitle,'maxlength="300"')}${selectField('作品类型','media',Object.entries(C.mediaNames),i.media)}${selectField('收藏位置','inWatchlist',[['yes','加入追番追更'],['no','仅存作品库（不在待看区）']],C.isWatching(i)?'yes':'no')}${selectField('追番分区（加入待看时使用）','type',[['daily','每日更新'],['binge','完结待看'],['manga','漫画待看'],['novel','小说待看']],i.type)}${selectField('观看 / 阅读状态','status',Object.entries(C.statuses),i.status)}${selectField('观看优先级（独立于评分）','priority',[['SSR','SSR · 最优先'],['SR','SR · 比较想看'],['R','R · 有空再看']],i.priority)}${selectField('更新星期','weekday',[['','不指定'],...C.weekdays.map(d=>[d,d])],i.weekday)}${field('我的评分（留空 = 未评分）','score',i.score??'','type="number" min="0" max="10" step="0.1" placeholder="例如 9.8"')}${field('已看 / 已读进度','current',i.current,'type="number" min="0" step="1" required')}${field('总集数 / 总话数（未知留空）','total',i.total,'type="number" min="1" step="1"')}${selectField('进度单位','unit',[['集','集'],['话','话'],['卷','卷'],['章','章']],i.unit)}${field('系列名称（同名会互相关联）','series',i.series,'maxlength="300" placeholder="例如 游戏人生"')}<div class="form-section">封面与标签</div><div class="field full"><label for="f-image">封面图片网址</label><input id="f-image" name="image" value="${esc(i.image.startsWith('data:')?'':i.image)}" placeholder="https://…"><div class="cover-upload-preview"><input type="file" id="cover-upload" accept="image/png,image/jpeg,image/webp,image/gif" aria-label="上传封面"><span id="cover-upload-state" class="small muted">也可上传本机图片，自动缩小保存。</span></div>${i.image?'<label class="check-label"><input type="checkbox" name="removeImage">移除现有封面</label>':''}</div><div class="field full"><label for="f-tags">题材 / 作品标签（用逗号分隔）</label><input id="f-tags" name="tags" value="${esc(i.tags.join('，'))}" placeholder="奇幻，冒险，日常"></div><div class="field full"><label for="f-personalTags">个人标签（用逗号分隔）</label><input id="f-personalTags" name="personalTags" value="${esc(i.personalTags.join('，'))}" placeholder="后劲大，想重看，音乐喜欢"></div>${field('来源网址 / Bangumi 链接','sourceUrl',i.sourceUrl,'type="url"')}${field('年份','year',i.year,'maxlength="4" pattern="[0-9]{4}|" placeholder="例如 2026"')}<div class="full"><label class="check-label"><input name="favorite" type="checkbox" ${i.favorite?'checked':''}>标为心头好，优先放在作品库前面</label></div><div class="form-section">自己的感受</div><div class="field full"><label for="f-review">我的长评</label><textarea id="f-review" name="review" rows="5" placeholder="为什么喜欢，什么让你记住了它…">${esc(i.review)}</textarea></div><div class="field full"><label for="f-note">备注（保留原追番表备注）</label><textarea id="f-note" name="note" rows="2">${esc(i.note)}</textarea></div><details class="full"><summary class="small muted">作品简介</summary><textarea name="summary" style="width:100%;margin-top:10px" rows="4" aria-label="作品简介">${esc(i.summary)}</textarea></details></div>${errorBox()}</form>`,`${btn('close','取消')}<button class="btn primary" type="submit" form="work-form">保存作品</button>`);
    $('work-form')._cover=i.image;updateMediaFields(false);updateWatchFields();
  }
  function updateMediaFields(changed){const form=$('work-form');if(!form)return;const media=form.elements.media.value;if(media==='anime'){if(!['daily','binge'].includes(form.elements.type.value))form.elements.type.value='binge';}else form.elements.type.value=media;
    [...form.elements.type.options].forEach(o=>o.disabled=media==='anime'?!['daily','binge'].includes(o.value):o.value!==media);
    form.elements.weekday.disabled=form.elements.type.value!=='daily';if(form.elements.type.value==='daily'&&!form.elements.weekday.value)form.elements.weekday.value='周一';
    if(changed)form.elements.unit.value=media==='anime'?'集':media==='manga'?'话':'卷';
  }
  function updateWatchFields(){const form=$('work-form');if(!form)return;const ended=['done','dropped'].includes(form.elements.status.value);if(ended)form.elements.inWatchlist.value='no';form.elements.inWatchlist.disabled=ended;}
  async function setWatchPosition(id,action,showDetail=false){
    const i=item(id);if(!i||!EDIT)return;
    if(action==='add'&&['done','dropped'].includes(i.status))throw new Error('请先编辑作品，将状态改为想看 / 在看，再加入追番追更。');
    await mutate(()=>{i.inWatchlist=action==='add';if(action==='complete'){i.status='done';i.finishedAt=C.now();if(i.total!=='')i.current=i.total;}i.updatedAt=C.now();},action==='add'?'已加入待看':action==='complete'?'已标记完成，作品与评价保留在作品库':'已移出待看，作品与评价保留在作品库',true);
    if(showDetail)detail(id);
  }
  async function compress(file){if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type))throw new Error('请选择 PNG、JPG、WebP 或 GIF 图片');if(file.size>20*1024*1024)throw new Error('图片请控制在 20 MB 以内');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,600/img.width,900/img.height),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.84);}finally{URL.revokeObjectURL(url);}}
  async function saveForm(form){const old=item(form.dataset.id),v=Object.fromEntries(new FormData(form));if(v.image&&!C.safeURL(v.image,true))throw new Error('封面网址需要以 http:// 或 https:// 开头');if(v.total&&Number(v.current)>Number(v.total))throw new Error('当前进度不能超过总数；总数未知时请留空');
    const next=C.normalize({...old,...v,inWatchlist:v.inWatchlist==='yes',bangumiId:C.subjectId(v.sourceUrl)||old?.bangumiId||'',id:old?.id||C.uid(),favorite:!!v.favorite,image:v.removeImage?'':v.image||form._cover||'',updatedAt:C.now(),createdAt:old?.createdAt||C.now()});
    if(next.score!==null&&next.score!==old?.score)next.scoreHistory.push({score:next.score,at:C.now()});if(next.status==='done'&&old?.status!=='done')next.finishedAt=C.now();
    await mutate(()=>{if(old)state.payload.items=state.payload.items.map(x=>x.id===old.id?next:x);else state.payload.items.unshift(next);},'作品已保存到本机');closeModal();detail(next.id);
  }
  async function increment(id,showDetail=false){const i=item(id);if(!i||!EDIT||i.total!==''&&i.current>=i.total)return;
    await mutate(()=>{i.current++;i.updatedAt=C.now();if(i.total!==''&&i.current>=i.total){i.status='done';i.inWatchlist=false;i.finishedAt=C.now();}else i.status='doing';},i.total!==''&&i.current>=i.total?'进度已保存':'进度已保存',true);if(showDetail)detail(id);
  }
  function textEditor(id,kind,commentId=''){const i=item(id);if(!i)return;const n=i.comments.find(x=>x.id===commentId);modal(kind==='review'?'编辑我的长评':'编辑随手记',`<form id="text-form" data-id="${esc(id)}" data-kind="${kind}" data-comment="${esc(commentId)}"><textarea name="text" rows="10" style="width:100%" aria-label="评语内容" ${kind==='comment'?'required':''}>${esc(kind==='review'?i.review:n?.text||'')}</textarea></form>`,`${btn('close','取消')}<button class="btn primary" type="submit" form="text-form">保存</button>`);}
  function importDialog(tab='search'){
    if(!EDIT)return;abortImport?.abort();pending=[];pendingKind=tab;
    const tabs=[['search','搜索 / 链接'],['account','我的 Bangumi 收藏'],['backup','旧表 / JSON 备份'],['extension','原版导入插件']];
    let html='';
    if(tab==='search')html=`<form id="bgm-search-form" class="stack"><div class="field"><label for="bgm-query">输入作品名称，或粘贴 Bangumi 链接 / ID</label><input id="bgm-query" required placeholder="例如：游戏人生，或 https://bgm.tv/subject/…"></div><div class="row"><select id="bgm-media" aria-label="搜索作品类型"><option value="2">动画</option><option value="1">漫画 / 小说</option></select><button class="btn primary" type="submit">搜索作品</button></div><small class="muted">可粘贴多个条目链接或 ID，用空格、逗号或换行分隔。名称搜索一次显示 20 条结果。</small></form>`;
    if(tab==='account')html=`<form id="bgm-account-form" class="stack"><div class="field"><label for="bgm-user">Bangumi 用户名或个人主页链接</label><input id="bgm-user" required placeholder="例如 https://bgm.tv/user/用户名"></div><div class="row"><select id="bgm-collection" aria-label="收藏状态"><option value="">全部收藏状态</option>${[['1','想看'],['2','看过'],['3','在看'],['4','搁置'],['5','抛弃']].map(([k,v])=>option(k,v,'')).join('')}</select><button class="btn primary" type="submit">读取收藏</button></div><small class="muted">导入动画与书籍，带上已有整数评分、短评、标签和进度。漫画 / 小说可在预览中修正分类。</small></form>`;
    if(['search','account'].includes(tab))html+=`<details class="mt"><summary class="small muted">可选：Bangumi Access Token（私有收藏需要）</summary><div class="field mt"><input id="bgm-token" type="password" autocomplete="off" value="${esc(bgmToken)}" aria-label="Bangumi Access Token" placeholder="仅在当前页面使用，不发布、不写入备份"><small>在 <a href="https://next.bgm.tv/demo/access-token" target="_blank" rel="noopener noreferrer">Bangumi 授权页面</a> 生成。请勿填写账号密码。</small></div></details>`;
    if(tab==='backup')html=`<div class="stack"><div class="notice">兼容原追番表的数组、version 3，以及新版 version 4 备份。旧记录的优先级、进度和备注都会保留。</div><label class="field">选择 JSON 文件<input type="file" id="backup-file" accept=".json,application/json"></label><p class="small muted">先预览，再选择“补全资料”或“替换重复记录”。加密备份会先要求解锁。</p></div>`;
    if(tab==='extension')html=`<p class="small muted">兼容压缩包原来的 Bangumi-Watchlist-Importer-v2 插件。在 Bangumi 页面选好分类并导入后，回到本地 editor.html 读取队列。</p><ol class="steps"><li>Chrome / Edge 扩展管理中加载插件文件夹。</li><li>在扩展详情开启“允许访问文件网址”。</li><li>从 Bangumi 导入后，点击下方按钮。</li></ol>${btn('extension-read','读取插件队列','primary')}<p class="small muted mt">这个插件桥接入口用于本地 HTML；网站端直接使用名称搜索、链接和账号导入。</p>`;
    modal('把喜欢的故事带进来',`<div class="import-tabs">${tabs.map(([k,v])=>`<button class="pill ${tab===k?'active':''}" data-action="import-tab" data-value="${k}">${v}</button>`).join('')}</div>${html}${errorBox()}<div id="import-status" class="busy-line" role="status"></div><div id="import-results"></div>`,'',true);
  }
  async function api(path,options={},signal){
    const headers={'Accept':'application/json'};if(options.body)headers['Content-Type']='application/json';if(bgmToken)headers.Authorization='Bearer '+bgmToken;
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);const forward=()=>controller.abort();signal?.addEventListener('abort',forward,{once:true});
    try{const r=await fetch('https://api.bgm.tv'+path,{...options,headers,signal:controller.signal});if(!r.ok)throw new Error(r.status===401?'Bangumi Token 无效或已过期':r.status===404?'条目不存在，或需要 Bangumi 授权':r.status===429?'Bangumi 请求过于频繁，请稍后再试':'Bangumi 返回 HTTP '+r.status);return await r.json();}
    catch(e){if(signal?.aborted)throw new Error('已取消读取');if(e.name==='AbortError')throw new Error('Bangumi 请求超时，请稍后重试，或使用原版导入插件');if(e instanceof TypeError)throw new Error('无法连接 Bangumi；请检查网络，或使用原版导入插件 / JSON 导入');throw e;}
    finally{clearTimeout(timer);signal?.removeEventListener('abort',forward);}
  }
  const pause=ms=>new Promise(r=>setTimeout(r,ms));
  function importStatus(s){if($('import-status'))$('import-status').textContent=s;}
  async function doSearch(form){bgmToken=$('bgm-token')?.value.trim()||'';abortImport?.abort();const ctrl=new AbortController();abortImport=ctrl;const query=$('bgm-query').value.trim(),ids=[...new Set(query.split(/[\s,，]+/).map(C.subjectId).filter(Boolean))];pending=[];const button=form.querySelector('button[type=submit]');button.disabled=true;importStatus('正在读取 Bangumi…');$('import-results').innerHTML='';$('form-error').hidden=true;
    try{if(ids.length){if(ids.length>100)throw new Error('一次最多读取 100 个链接');for(const id of ids){if(ctrl.signal.aborted)break;const s=await api('/v0/subjects/'+id,{},ctrl.signal);pending.push(C.bgmSubject(s));importStatus(`已读取 ${pending.length} / ${ids.length} 部作品`);await pause(180);}}
      else{const p=await api('/v0/search/subjects?limit=20&offset=0',{method:'POST',body:JSON.stringify({keyword:query,sort:'match',filter:{type:[Number($('bgm-media').value)]}})},ctrl.signal);pending=(p.data||[]).filter(s=>[1,2].includes(Number(s.type))).map(s=>({...C.bgmSubject(s),_needsDetails:true}));}
      if(!ctrl.signal.aborted){pendingKind='bangumi';renderImportPreview();importStatus(pending.length?`找到 ${pending.length} 部作品，请核对并勾选。`:'没有找到条目，可以换一个名称或直接粘贴条目链接。');}
    }catch(e){if(!ctrl.signal.aborted){formError(e);if(pending.length){pendingKind='bangumi';renderImportPreview();importStatus('以上为已读取的部分结果，可以先导入。');}}}finally{button.disabled=false;}
  }
  async function doAccount(form){bgmToken=$('bgm-token')?.value.trim()||'';let user=$('bgm-user').value.trim();if(/^https?:/.test(user)){try{const u=new URL(user);if(!['bgm.tv','bangumi.tv','chii.in'].includes(u.hostname))throw 0;user=decodeURIComponent(u.pathname.match(/^\/user\/([^/]+)/)?.[1]||'');}catch{throw new Error('请输入正确的 Bangumi 个人主页链接');}}
    if(!user)throw new Error('未找到 Bangumi 用户名');abortImport?.abort();const ctrl=new AbortController();abortImport=ctrl;pending=[];const button=form.querySelector('button[type=submit]');button.disabled=true;const status=$('bgm-collection').value;$('form-error').hidden=true;$('import-results').innerHTML='';importStatus('正在读取收藏…关闭窗口可取消。');
    try{for(const type of [2,1]){let offset=0;while(true){if(ctrl.signal.aborted)break;const p=await api('/v0/users/'+encodeURIComponent(user)+'/collections?subject_type='+type+'&limit=100&offset='+offset+(status?'&type='+status:''),{},ctrl.signal);const list=p.data||[];for(const col of list){if(col.subject)pending.push(C.bgmSubject({...col.subject,id:col.subject_id,type:col.subject_type||type},col));}offset+=list.length;importStatus(`已读取 ${pending.length} 部收藏…`);if(!list.length||offset>=p.total)break;if(pending.length>=10000)throw new Error('已读取 10000 部收藏，请分状态继续导入');await pause(220);}if(ctrl.signal.aborted)break;}
      if(!ctrl.signal.aborted){pendingKind='account';renderImportPreview();importStatus(`读取完成，共 ${pending.length} 部。进度与评分可在导入后继续调整。`);}
    }catch(e){if(!ctrl.signal.aborted){formError(e);if(pending.length){pendingKind='account';renderImportPreview();importStatus('部分页面读取失败，已读取的收藏可以先导入；稍后重试会去重。');}}}finally{button.disabled=false;}
  }
  function renderImportPreview(){const el=$('import-results');if(!el)return;if(!pending.length){el.innerHTML='';return;}el.innerHTML=`<div class="spread"><label class="check-label"><input type="checkbox" id="select-all-import" ${pendingKind==='bangumi'?'':'checked'}>全选 / 取消</label><span class="small muted">重名作品按 Bangumi ID 优先去重</span></div><div class="preview-list">${pending.map((i,n)=>{const old=C.duplicate(state.payload.items,i);return `<div class="import-result"><input type="checkbox" class="import-check" value="${n}" ${pendingKind==='bangumi'?'':'checked'} aria-label="导入 ${esc(i.title)}">${i.image?`<img src="${esc(i.image)}" alt="" referrerpolicy="no-referrer" loading="lazy">`:'<span class="avatar">书</span>'}<div><strong>${esc(i.title)}</strong><small class="muted">${old?'已有记录 · 将按下方规则处理':'新作品'}${i.classificationUncertain?' · 请确认类型':''}${i.score!==null?' · 我的评分 '+i.score.toFixed(1):''}</small></div><select class="import-media" data-index="${n}" aria-label="${esc(i.title)}的类型">${Object.entries(C.mediaNames).map(([k,v])=>option(k,v,i.media)).join('')}</select></div>`;}).join('')}</div><div class="row"><label class="small" for="import-mode">重复条目：</label><select id="import-mode"><option value="fill">只补全空白资料，保留我的评分 / 评语 / 进度</option><option value="skip">跳过已有作品</option>${pendingKind==='backup'||pendingKind==='account'?'<option value="replace">用导入记录替换重复作品（含个人评分、评语）</option>':''}</select></div><div class="row mt" style="justify-content:flex-end">${btn('commit-import','导入选中作品','primary')}</div>`;}
  async function readBackup(file){if(!file)return;if(file.size>50*1024*1024)throw new Error('备份文件超过 50 MB，请分批导入');let raw=JSON.parse((await file.text()).replace(/^\uFEFF/,''));if(raw.encrypted){const pw=await askPassword('解锁备份','输入导出这份备份时设置的口令。');if(pw===null)return;raw=await C.decrypt(raw,pw);importDialog('backup');}const data=C.parsePayload(raw);pending=data.items;pendingKind='backup';renderImportPreview();importStatus(`备份包含 ${pending.length} 部作品，尚未修改本机记录。`);}
  async function commitImport(button){const picked=[...document.querySelectorAll('.import-check:checked')].map(x=>Number(x.value));if(!picked.length)throw new Error('请先勾选要导入的作品');const mode=$('import-mode').value;if(mode==='replace'&&!confirm('这会替换重复作品的评分、评语和进度。确定继续吗？'))return;
    const choices=new Map([...document.querySelectorAll('.import-media')].map(x=>[Number(x.dataset.index),x.value]));button.disabled=true;const ctrl=new AbortController();abortImport=ctrl;const incoming=[];
    try{for(const n of picked){if(ctrl.signal.aborted)return;let i=pending[n];if(i._needsDetails){try{i=C.bgmSubject(await api('/v0/subjects/'+i.bangumiId,{},ctrl.signal));}catch(e){if(ctrl.signal.aborted)return;importStatus('部分详情暂时不可用，将保留搜索结果资料。');}}const media=choices.get(n);i=C.normalize({...i,media,type:media==='anime'?['daily','binge'].includes(i.type)?i.type:'binge':media,unit:media===i.media?i.unit:media==='anime'?'集':media==='manga'?'话':'卷'});delete i._needsDetails;incoming.push(i);}
      const merged=C.merge(state.payload.items,incoming,mode);await mutate(()=>{state.payload.items=merged.items;},`已导入：新增 ${merged.added}，补全 / 替换 ${merged.updated}，跳过 ${merged.skipped}`,true);
      if(pendingKind==='extension')window.postMessage({source:'anime-watchlist-html',type:'CLEAR_IMPORTED',bangumiIds:incoming.map(i=>i.bangumiId).filter(Boolean)},'*');closeModal();
    }finally{button.disabled=false;}
  }
  function askPassword(title,description){return new Promise(resolve=>{const d=modal(title,`<form id="password-form"><p class="small muted" style="margin-bottom:15px">${esc(description)}</p><input type="password" name="password" required autocomplete="current-password" aria-label="解锁口令" style="width:100%"></form>`,`<button class="btn" data-action="close">取消</button><button class="btn primary" form="password-form" type="submit">解锁</button>`);let resolved=false;$('password-form').onsubmit=e=>{e.preventDefault();resolved=true;const p=new FormData(e.target).get('password');closeModal();resolve(p);};d.addEventListener('close',()=>{if(!resolved)resolve(null);},{once:true});});}
  async function unpack(raw){if(!raw.encrypted)return C.parsePayload(raw);if(password){try{return await C.decrypt(raw,password);}catch{}}const pw=await askPassword('解锁作品库','这份作品数据已加密。口令只在当前页面内使用。');if(pw===null)throw new Error('已取消解锁');const p=await C.decrypt(raw,pw);password=pw;return p;}
  function renderLock(){root.innerHTML=`<main class="workspace"><div class="locked">${ico('lock')}<div class="eyebrow">HHD · PRIVATE COLLECTION</div><h1>故事，只留给你。</h1><p>输入口令，打开你的作品收藏。${state.cache?'当前使用已保存的离线副本。':''}</p><form id="unlock-form"><input type="password" name="password" required autocomplete="current-password" placeholder="输入作品库口令" aria-label="作品库口令"><button class="btn primary" type="submit">解锁作品库 ${ico('arrow')}</button>${errorBox()}</form><div class="lock-meta">口令不会写入网页或上传到 GitHub。</div></div></main>`;}
  async function loadViewer(){const seq=++viewLoadSeq;try{let raw;state.cache=false;try{const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const r=await fetch('./data.json?t='+Date.now(),{cache:'no-store',signal:controller.signal});if(!r.ok)throw new Error('HTTP '+r.status);raw=await r.json();}finally{clearTimeout(timeout);}await storePut('published',raw);}catch(e){raw=await storeGet('published');if(!raw)throw e;state.cache=true;}if(seq!==viewLoadSeq)return;if(raw.encrypted){state.payload=C.parsePayload({items:[]});state.locked=raw;if(password){try{state.payload=await C.decrypt(raw,password);state.locked=null;}catch{password='';}}}else{state.payload=C.parsePayload(raw);state.locked=null;}state.notice=state.cache?'当前为缓存副本，联网后点“刷新”获取最新发布。':'';render();}
    catch(e){state.notice=location.protocol==='file:'?'本地预览无法直接读取 data.json。请双击 editor.html 使用；发布到 GitHub Pages 后可正常浏览。':'读取作品库失败：'+e.message+'。请稍后刷新。';render();}}
  function settingsHTML(){return `<div class="settings-card"><section class="settings-section"><h3>你的收藏室</h3><form id="title-form" class="row"><input name="title" value="${esc(state.payload.title)}" maxlength="80" required aria-label="作品库名称" ${EDIT?'':'disabled'}>${EDIT?'<button class="btn" type="submit">保存名称</button>':''}</form><p>所有编辑先保存到当前设备。点击“发布到 GitHub”后，其他设备刷新可看到修改。跨设备编辑前，先读取 GitHub 最新记录。</p>${!EDIT?btn('open-editor',ico('edit')+'进入编辑器','primary'):''}</section><section class="settings-section"><h3>导入与备份</h3><div class="row">${EDIT?btn('import','Bangumi / 旧表导入'):''}${btn('export',ico('download')+'导出 JSON 备份')}${btn('export-encrypted',ico('lock')+'导出加密备份')}${EDIT?btn('restore-safety','读取上次操作前的备份'):''}</div><p>普通 JSON 备份包含封面、评分、标签、长评和随手记，不包含 Token。加密备份需要口令才能导入。清理浏览器数据前请导出。</p></section>${EDIT?`<section class="settings-section"><h3>GitHub 发布与跨设备读取</h3><p>使用你原来的 GitHub Pages 仓库。只更新作品库文件，保留仓库中的其他文件。</p><form id="github-form"><div class="form-grid">${field('GitHub 用户名','owner',config.owner||'','required autocomplete="username" placeholder="你的 GitHub 用户名"')}${field('仓库名','repo',config.repo||'','required placeholder="例如 anime-watchlist"')}${field('分支','branch',config.branch||'main','required')}${field('网站地址（可选，用于自定义域名）','pagesUrl',config.pagesUrl||'','type="url" placeholder="留空自动生成"')}<div class="field full"><label for="github-token">GitHub Fine-grained Token</label><input name="token" id="github-token" type="password" autocomplete="off" value="${esc(ghToken)}" placeholder="仅授权此仓库，Contents: Read and write"><small>只发送到 api.github.com，不写入网页、作品数据或导出文件。</small></div><div class="full"><label class="check-label"><input name="remember" type="checkbox" ${config.remember?'checked':''}>在当前设备浏览器记住 Token（自己的设备才勾选）</label></div><div class="full"><label class="check-label"><input name="encrypted" id="publish-encrypted" type="checkbox" ${config.encrypted?'checked':''}>加密发布作品数据</label><p>GitHub Pages 网页可被访问；启用后，作品标题、封面、评分和评语先加密，打开网站需要口令。本机编辑缓存与普通备份仍为明文。</p></div><div id="encryption-fields" class="full form-grid" ${config.encrypted?'':'hidden'}><div class="field"><label for="publish-password">作品库口令（至少 8 个字符）</label><input type="password" id="publish-password" name="password" autocomplete="new-password" value="${esc(password)}"></div><div class="field"><label for="publish-password-confirm">再输入一次口令</label><input type="password" id="publish-password-confirm" name="passwordConfirm" autocomplete="new-password" value="${esc(password)}"></div><small class="full muted">口令不会保存或发布，遗忘后无法恢复加密文件；请另存一份备份。启用加密不会删除此前公开版本的 Git 历史。</small></div></div><div class="row mt"><button class="btn" type="submit">保存设置</button>${btn('test-github','测试连接')}${btn('pull-github',ico('download')+'读取 GitHub')}${btn('publish',ico('cloud')+'发布到 GitHub','primary',state.busy?'disabled':'')}</div></form><div id="github-status" class="busy-line" role="status"></div>${errorBox()}<details class="mt"><summary class="small">第一次配置怎么做？</summary><ol class="steps"><li>在 GitHub 创建或打开原仓库，确保已有 main 分支（创建时勾选 README）。</li><li>Settings → Developer settings → Personal access tokens → Fine-grained tokens。</li><li>只选择此仓库，Repository permissions 的 Contents 设为 Read and write。</li><li>将用户名、仓库、Token 填入上方，测试连接后发布。</li><li>仓库 Settings → Pages → Deploy from a branch → main / (root) → Save。</li><li>等待 Pages 构建完成，再打开网站地址。手机点“进入编辑”也能修改，发布需在该设备填 Token。</li></ol></details></section>`:''}<section class="settings-section"><h3>离线与外观</h3><div class="row">${btn('theme',ico('moon')+'切换明暗主题')}${btn('refresh',ico('refresh')+(EDIT?'检查网页数据':'刷新已发布数据'))}${EDIT?btn('fill-covers','补全缺失封面'):''}${btn('cache-offline','准备离线阅读')}</div><p>网站通过 HTTPS 打开后会缓存页面与已发布数据；封面首次查看需要联网。点击“准备离线阅读”可提前加载封面。离线无法导入 Bangumi 或发布 GitHub。浏览器可能回收缓存，备份文件应另外保留。</p><p>当前：${location.protocol==='file:'?'本地文件模式（无需服务即可编辑）':navigator.onLine?'网站在线模式':'离线模式'}。${storageFallback?'当前使用容量较小的本地存储，请及时导出备份。':'作品编辑使用浏览器本机数据库保存。'}</p></section><section class="settings-section"><h3>发布前检查</h3><p>普通发布会公开作品数据；个人使用不等于访问受限。如果希望别人看不到内容，请勾选加密发布。SSR / SR / R 只表示想看的优先级，0.0–10.0 表示你自己的评分。</p></section></div>`;}
  function publicConfig(cfg=config){return {owner:cfg.owner||'',repo:cfg.repo||'',branch:cfg.branch||'main',pagesUrl:cfg.pagesUrl||'',encrypted:!!cfg.encrypted};}
  function repoKey(cfg=config){return `${cfg.owner}/${cfg.repo}@${cfg.branch}`.toLowerCase();}
  function getConfigFromForm(){const form=$('github-form');if(!form)return config;const v=Object.fromEntries(new FormData(form));const next={owner:(v.owner||'').trim(),repo:(v.repo||'').trim().replace(/\.git$/,''),branch:(v.branch||'main').trim(),pagesUrl:(v.pagesUrl||'').trim(),remember:!!v.remember,encrypted:!!v.encrypted};if(next.owner&&!/^[a-zA-Z0-9-]+$/.test(next.owner))throw new Error('GitHub 用户名格式不正确');if(next.repo&&!/^[\w.-]+$/.test(next.repo))throw new Error('仓库名格式不正确');if(next.pagesUrl&&!C.safeURL(next.pagesUrl))throw new Error('网站地址不正确');if(next.branch.includes('..')||next.branch.startsWith('/'))throw new Error('分支名格式不正确');
    ghToken=(v.token||'').trim();config=next;setLocal(settingKey,config);if(config.remember)setLocal('hhdShelfToken_v4',ghToken);else{localStorage.removeItem('hhdShelfToken_v4');}try{sessionStorage.setItem('hhdShelfSessionToken_v4',ghToken);}catch{}
    if(v.password){if(v.password!==v.passwordConfirm)throw new Error('两次输入的作品库口令不一致');password=v.password;}if(!config.encrypted)password='';return config;
  }
  function requireConfig(token=true){getConfigFromForm();if(!config.owner||!config.repo||!config.branch||token&&!ghToken)throw new Error('请先填写 GitHub 用户名、仓库、分支和 Token');return config;}
  function pagesURL(){if(config.pagesUrl)return config.pagesUrl;return `https://${config.owner}.github.io/${config.repo.toLowerCase()===config.owner.toLowerCase()+'.github.io'?'':encodeURIComponent(config.repo)+'/'}`;}
  function ghStatus(s){if($('github-status'))$('github-status').textContent=s;else if(s)toast(s);}
  async function github(path,method='GET',body=null){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const headers={'Accept':'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'};if(ghToken)headers.Authorization='Bearer '+ghToken;if(body)headers['Content-Type']='application/json';const url='https://api.github.com/repos/'+encodeURIComponent(config.owner)+'/'+encodeURIComponent(config.repo)+path;const r=await fetch(url,{method,headers,body:body?JSON.stringify(body):undefined,signal:controller.signal,cache:'no-store'});if(!r.ok){const msg=r.status===401?'Token 无效或已过期':r.status===403?'权限不足或请求次数受限；请检查此仓库的 Contents 读写权限':r.status===404?'仓库、分支不存在，或 Token 无权访问':r.status===409||r.status===422?'远程发生冲突，或仓库尚未初始化。请先读取 GitHub；新仓库请创建 README / main 分支':'请求失败';const err=new Error('GitHub '+r.status+'：'+msg);err.status=r.status;throw err;}return r.status===204?null:await r.json();}catch(e){if(e.name==='AbortError')throw new Error('GitHub 请求超时；请先检查远程仓库状态再重试');if(e instanceof TypeError)throw new Error('无法连接 GitHub，请检查网络后重试');throw e;}finally{clearTimeout(timer);}}
  async function remoteSnapshot(){const branch=config.branch.split('/').map(encodeURIComponent).join('/');const ref=await github('/git/ref/heads/'+branch);const commit=await github('/git/commits/'+ref.object.sha);const tree=await github('/git/trees/'+commit.tree.sha);if(tree.truncated)throw new Error('仓库根目录过大，无法安全读取完整文件列表');return {head:ref.object.sha,tree:commit.tree.sha,entries:tree.tree,dataSha:tree.tree.find(x=>x.path==='data.json')?.sha||''};}
  async function remoteData(snapshot){if(!snapshot.dataSha)throw new Error('仓库内还没有 data.json，可以先发布本机作品库');const b=await github('/git/blobs/'+snapshot.dataSha);if(b.encoding!=='base64')throw new Error('GitHub 返回了不支持的数据编码');return JSON.parse(new TextDecoder().decode(C.un64(b.content.replace(/\s/g,''))).replace(/^\uFEFF/,''));}
  async function pullGithub(){requireConfig(false);if(state.busy)return;state.busy=true;document.querySelectorAll('[data-action="refresh"],[data-action="pull-github"]').forEach(b=>b.disabled=true);ghStatus('正在读取 GitHub 最新版本…');try{const snap=await remoteSnapshot(),raw=await remoteData(snap),p=await unpack(raw);config.encrypted=!!raw.encrypted;setLocal(settingKey,config);let choose='replace';if(state.dirty){const d=modal('读取 GitHub 作品库',`<p class="prose">GitHub：${p.items.length} 部作品\n当前设备：${state.payload.items.length} 部作品${state.dirty?'（有未发布修改）':''}</p><p class="small muted mt">替换前会在本机保存一份恢复备份。合并会保留本机的评分、评语和进度，只添加新作品、补全空白资料。</p>`,`${btn('pull-choice','取消','','data-value="cancel"')}${btn('pull-choice','合并到本机','','data-value="merge"')}${btn('pull-choice','用 GitHub 版本替换本机','primary','data-value="replace"')}`);choose=await new Promise(resolve=>{let done=false;d.addEventListener('click',e=>{const b=e.target.closest('[data-action="pull-choice"]');if(b){done=true;const value=b.dataset.value;closeModal();resolve(value);}});d.addEventListener('close',()=>{if(!done)resolve('cancel');},{once:true});});}
      if(choose==='cancel')return;await storePut('safety',payload());const previous={payload:state.payload,remoteSha:state.remoteSha,repoKey:state.repoKey,dirty:state.dirty};state.payload=choose==='merge'?{...p,items:C.merge(state.payload.items,p.items,'fill').items}:p;state.remoteSha=snap.dataSha;state.repoKey=repoKey();state.dirty=choose==='merge';try{await persist();}catch(e){Object.assign(state,previous);throw e;}state.notice='';state.busy=false;render();toast(choose==='merge'?'已合并到本机，发布后同步到其他设备':'已读取 GitHub 最新记录');
    }finally{state.busy=false;document.querySelectorAll('[data-action="refresh"],[data-action="pull-github"],[data-action="publish"]').forEach(b=>b.disabled=false);ghStatus('');}}
  function serializeJSON(v){return JSON.stringify(v).replace(/</g,'\\u003c').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029');}
  function buildHTML(role,seed={items:[]}){
    const code=id=>document.getElementById(id).textContent.replace(/<\/script/gi,'<\\/script');
    return '<!doctype html>\n<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#f6f5f1"><meta name="anime-watchlist-template" content="4"><meta name="referrer" content="no-referrer"><meta name="description" content="王之宝库 · 记录你喜欢的动画、漫画与小说"><title>王之宝库</title><link rel="icon" href="./icon.svg" type="image/svg+xml"><link rel="manifest" href="./manifest.webmanifest"><style id="app-style">'+document.getElementById('app-style').textContent+'</style></head><body><div id="app"><div class="loading">正在打开作品库…</div></div><script id="boot-data" type="application/json">'+serializeJSON({role,seed,config:publicConfig()})+'</scr'+'ipt><script id="core-script">'+code('core-script')+'</scr'+'ipt><script id="app-script">'+code('app-script')+'</scr'+'ipt><script id="asset-data" type="application/json">'+document.getElementById('asset-data').textContent+'</scr'+'ipt></body></html>';
  }
  async function publish(){if(!EDIT||state.busy)return;if(!$('github-form')){state.view='settings';render();}
    try{requireConfig();if(config.encrypted&&password.length<8)throw new Error('请填写并确认至少 8 个字符的作品库口令');}catch(e){formError(e);return;}
    state.busy=true;document.querySelectorAll('[data-action="publish"]').forEach(b=>b.disabled=true);
    try{await persist();ghStatus('检查远程版本…');const snap=await remoteSnapshot();
      if(state.repoKey===repoKey()&&state.remoteSha&&snap.dataSha!==state.remoteSha)throw new Error('另一台设备已经更新 GitHub。请先“读取 GitHub”合并或替换，再发布；本机修改已保留。');
      if(snap.dataSha&&(!state.remoteSha||state.repoKey!==repoKey())){if(!confirm('这是当前设备首次向这个仓库发布，尚未与远程版本对齐。建议取消后先“读取 GitHub”。\n\n继续会使用本机 '+state.payload.items.length+' 部作品更新远程 data.json，确定继续吗？'))return;}
      const doc={...payload(),publishedAt:C.now()};ghStatus(config.encrypted?'正在加密作品数据…':'正在准备发布文件…');const outgoing=config.encrypted?await C.encrypt(doc,password):doc;
      const assets=JSON.parse($('asset-data').textContent);const files={'index.html':buildHTML('viewer'),'editor.html':buildHTML('editor'),'data.json':JSON.stringify(outgoing,null,2),'.nojekyll':'',...assets};
      const totalSize=Object.values(files).reduce((n,s)=>n+new Blob([s]).size,0);if(totalSize>35*1024*1024)throw new Error('发布包超过 35 MB，请缩小封面或先分批减少大图片');
      ghStatus('正在将页面与数据提交到同一个版本…');const tree=await github('/git/trees','POST',{base_tree:snap.tree,tree:Object.entries(files).map(([path,content])=>({path,mode:'100644',type:'blob',content}))});
      const commit=await github('/git/commits','POST',{message:'Update HHD workshelf '+new Date().toISOString(),tree:tree.sha,parents:[snap.head]});
      const latest=await github('/git/ref/heads/'+config.branch.split('/').map(encodeURIComponent).join('/'));if(latest.object.sha!==snap.head)throw new Error('发布期间远程仓库发生更新，未覆盖远程记录。请先读取 GitHub 后重试。');
      await github('/git/refs/heads/'+config.branch.split('/').map(encodeURIComponent).join('/'),'PATCH',{sha:commit.sha,force:false});
      const dataSha=tree.tree?.find(x=>x.path==='data.json')?.sha||'';
      state.remoteSha=dataSha||'';state.repoKey=repoKey();state.payload.publishedAt=doc.publishedAt;state.dirty=false;state.notice='已提交到 GitHub。Pages 仍需构建，通常需要稍等片刻；可在仓库 Actions 查看进度。';await persist();render();
      modal('已提交到 GitHub',`<p>已保存 ${doc.items.length} 部作品${config.encrypted?'（加密数据）':''}。</p><p class="small muted mt">网站在 Pages 构建完成后更新。第一次使用，请到仓库 Settings → Pages 选择 ${esc(config.branch)} 分支与 / (root)。</p><div class="notice mt"><a href="${esc(pagesURL())}" target="_blank" rel="noopener noreferrer">${esc(pagesURL())}</a></div><p class="small muted">电脑与手机均可使用上面这个地址。“进入编辑”可编辑本机副本，发布仍需 GitHub Token。</p>`,btn('close','完成','primary'));
    }catch(e){formError(e);ghStatus('发布未完成：'+e.message);}finally{state.busy=false;document.querySelectorAll('[data-action="publish"]').forEach(b=>b.disabled=false);}}
  async function fillCovers(){if(state.busy)return;const missing=state.payload.items.filter(i=>!i.image&&i.bangumiId);if(!missing.length){toast('已有 Bangumi 条目的封面都已齐全');return;}state.busy=true;let updated=0,failed=0;try{for(const i of missing){try{const n=C.bgmSubject(await api('/v0/subjects/'+i.bangumiId));i.image=n.image;updated++;}catch{failed++;}toast(`补全封面 ${updated+failed} / ${missing.length}`);await pause(200);}state.dirty=updated>0||state.dirty;await persist();render();toast(`补全 ${updated} 张封面${failed?'，'+failed+' 张暂时无法读取':''}`);}finally{state.busy=false;}}
  async function offlineCovers(){if(location.protocol==='file:'){toast('本地 editor.html 已可离线打开；已上传封面保存在本机。网站发布后可准备离线阅读。');return;}if(!('serviceWorker' in navigator)){toast('此浏览器不支持离线缓存');return;}toast('正在准备页面与封面缓存…');await navigator.serviceWorker.ready;let ok=0;const imgs=state.payload.items.map(i=>C.safeURL(i.image,true)).filter(Boolean);for(const u of imgs){if(u.startsWith('data:')){ok++;continue;}try{await fetch(u,{mode:'no-cors',credentials:'omit',referrerPolicy:'no-referrer'});ok++;}catch{}}toast(`已请求 ${ok} 张封面；可离线查看已成功缓存的内容。`);}
  document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement&&e.target.dataset.fallbackTitle){const p=document.createElement('div');p.innerHTML=fallback({title:e.target.dataset.fallbackTitle,media:e.target.dataset.media||'anime'});e.target.replaceWith(p.firstChild);}},true);
  document.addEventListener('click',async e=>{
    const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;e.preventDefault();
    if(state.busy&&['add','edit','edit-review','edit-comment','delete','delete-comment','save-score','plus','move-binge','complete-work','remove-watch','add-watch','favorite','commit-import','import','pull-github','undo','restore-safety'].includes(action)){toast('正在同步，请稍候再编辑。');return;}
    try{switch(action){
      case 'nav':state.view=b.dataset.view;state.filter={query:'',status:'',grade:'',tags:[],tagMode:'all',media:'all',favorite:false};render();window.scrollTo({top:0,behavior:'instant'});break;
      case 'theme':{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;setLocal('hhdShelfTheme_v4',next);break;}
      case 'media':state.filter.media=b.dataset.value;render();break;
      case 'layout':state.layout=b.dataset.value;render();break;
      case 'watch-tab':state.watch=b.dataset.value;state.filter={media:'all'};render();break;
      case 'tag-filter':closeModal();if(!['library','ranking'].includes(state.view))state.view='library';state.filter.tags=C.tags([...selectedTags(),b.dataset.tag]);delete state.filter.tag;render();break;
      case 'tag-picker':tagPicker();break;
      case 'apply-tags':state.filter.tags=[...document.querySelectorAll('.tag-pick:checked')].map(x=>x.value);state.filter.tagMode=$('tag-match-mode').value;delete state.filter.tag;closeModal();render();break;
      case 'reset-tag-picker':document.querySelectorAll('.tag-pick').forEach(x=>x.checked=false);break;
      case 'remove-tag':state.filter.tags=selectedTags().filter(t=>t!==b.dataset.tag);delete state.filter.tag;render();break;
      case 'clear-tags':state.filter.tags=[];delete state.filter.tag;render();break;
      case 'detail':detail(id);break;
      case 'add':editForm();break;
      case 'edit':editForm(id);break;
      case 'edit-review':textEditor(id,'review');break;
      case 'edit-comment':textEditor(id,'comment',b.dataset.comment);break;
      case 'close':closeModal();break;
      case 'favorite':await mutate(()=>{const i=item(id);i.favorite=!i.favorite;i.updatedAt=C.now();},'已更新心头好');detail(id);break;
      case 'save-score':{const input=$('quick-score');if(!input.checkValidity())throw new Error('请输入 0.0 到 10.0 的分数，最多一位小数');const value=C.score(input.value);await mutate(()=>{const i=item(id);if(i.score!==value&&value!==null)i.scoreHistory.push({score:value,at:C.now()});i.score=value;i.updatedAt=C.now();},value===null?'已设为未评分':'评分已保存');detail(id);break;}
      case 'plus':await increment(id,b.dataset.detail==='true');break;
      case 'complete-work':await setWatchPosition(id,'complete',b.dataset.detail==='true');break;
      case 'remove-watch':await setWatchPosition(id,'remove',b.dataset.detail==='true');break;
      case 'add-watch':await setWatchPosition(id,'add',b.dataset.detail==='true');break;
      case 'move-binge':await mutate(()=>{const i=item(id);i.type='binge';i.subtype=i.priority;i.updatedAt=C.now();},'已移入完结待看，保留原进度',true);break;
      case 'delete':if(confirm('删除「'+item(id).title+'」及它的评语和进度？删除后可撤销。')){await mutate(()=>{state.payload.items=state.payload.items.filter(i=>i.id!==id);},'作品已移除',true);closeModal();}break;
      case 'delete-comment':if(confirm('删除这条随手记？')){await mutate(()=>{const i=item(id);i.comments=i.comments.filter(n=>n.id!==b.dataset.comment);i.updatedAt=C.now();},'随手记已删除',true);detail(id);}break;
      case 'undo':if(undoState){state.payload=undoState;undoState=null;state.dirty=true;await persist();closeModal();render();toast('已撤销上一次操作');}break;
      case 'import':importDialog();break;
      case 'import-tab':importDialog(b.dataset.value);break;
      case 'commit-import':await commitImport(b);break;
      case 'extension-read':importStatus('正在连接原版插件…');window.postMessage({source:'anime-watchlist-html',type:'REQUEST_QUEUE'},'*');setTimeout(()=>{if($('import-status')?.textContent==='正在连接原版插件…')importStatus('未检测到插件。请在本地 editor.html 中使用，并开启扩展“允许访问文件网址”。');},2000);break;
      case 'export':download('HHD-作品库备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(payload(),null,2));toast('已导出完整备份，不包含账号 Token');break;
      case 'export-encrypted':{const pw=await askPassword('加密备份','请设置至少 8 个字符的备份口令，并妥善保存。遗忘后无法恢复这份加密备份。');if(pw!==null){const encrypted=await C.encrypt(payload(),pw);download('HHD-作品库加密备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(encrypted));toast('已导出加密备份');}break;}
      case 'restore-safety':{const p=await storeGet('safety');if(!p)throw new Error('还没有恢复备份。删除、导入或读取远程数据前会自动保存一份。');if(confirm('恢复到上一次删除 / 导入 / 读取远程数据之前的记录？当前记录将先导出备份。')){download('HHD-恢复前备份.json',JSON.stringify(payload(),null,2));state.payload=C.parsePayload(p);state.dirty=true;await persist();render();toast('已恢复到之前的本机记录');}break;}
      case 'open-editor':openEditor();break;
      case 'refresh':if(EDIT){if(config.owner&&config.repo)await pullGithub();else toast('本地记录已保存。跨设备读取请先配置 GitHub。');}else await loadViewer();break;
      case 'test-github':requireConfig();ghStatus('正在测试连接…');{const repo=await github('');await remoteSnapshot();ghStatus(`连接成功：${repo.full_name} · 分支 ${config.branch}。发布时将验证写入权限。`);}break;
      case 'pull-github':await pullGithub();break;
      case 'publish':await publish();break;
      case 'fill-covers':await fillCovers();break;
      case 'cache-offline':await offlineCovers();break;
    }}catch(err){formError(err);}
  });
  document.addEventListener('input',e=>{if(e.target.id==='tag-search'){const term=e.target.value.trim().toLocaleLowerCase();document.querySelectorAll('.tag-option').forEach(el=>el.hidden=!el.dataset.tagText.includes(term));}if(e.target.id==='search'){const pos=e.target.selectionStart;state.filter.query=e.target.value;render();$('search')?.focus();$('search')?.setSelectionRange(pos,pos);}});
  document.addEventListener('change',async e=>{const t=e.target;try{switch(t.id){
    case 'filter-status':state.filter.status=t.value;render();break;
    case 'filter-grade':state.filter.grade=t.value;render();break;
    case 'filter-sort':state.sort=t.value;render();break;
    case 'favorite-only':state.filter.favorite=t.checked;render();break;
    case 'rank-group':state.rankGroup=t.checked;render();break;
    case 'f-media':updateMediaFields(true);break;
    case 'f-type':updateMediaFields(false);break;
    case 'f-status':updateWatchFields();break;
    case 'publish-encrypted':$('encryption-fields').hidden=!t.checked;break;
    case 'cover-upload':if(t.files[0]){const f=$('work-form');f._cover=await compress(t.files[0]);$('cover-upload-state').textContent='封面已准备好，保存作品后生效。';$('f-image').value='';}break;
    case 'backup-file':await readBackup(t.files[0]);break;
    case 'select-all-import':document.querySelectorAll('.import-check').forEach(x=>x.checked=t.checked);break;
  }}catch(err){formError(err);}});
  document.addEventListener('submit',async e=>{const form=e.target;if(form.id==='password-form')return;e.preventDefault();if(state.busy&&!['unlock-form'].includes(form.id)){toast('正在同步，请稍候。');return;}const b=form.querySelector('button[type=submit]');try{switch(form.id){
    case 'work-form':await saveForm(form);break;
    case 'comment-form':{const text=new FormData(form).get('text').trim();if(!text)throw new Error('请先写下感想');await mutate(()=>{const i=item(form.dataset.id);i.comments.push({id:C.uid(),at:C.now(),text});i.updatedAt=C.now();},'感想已记下');detail(form.dataset.id);break;}
    case 'text-form':{const text=new FormData(form).get('text');await mutate(()=>{const i=item(form.dataset.id);if(form.dataset.kind==='review')i.review=text;else{const n=i.comments.find(x=>x.id===form.dataset.comment);if(n)n.text=text;}i.updatedAt=C.now();},'评语已保存');detail(form.dataset.id);break;}
    case 'title-form':await mutate(()=>{state.payload.title=new FormData(form).get('title').trim()||'王之宝库';},'名称已保存');break;
    case 'github-form':getConfigFromForm();toast('设置已保存到当前设备');break;
    case 'bgm-search-form':await doSearch(form);break;
    case 'bgm-account-form':await doAccount(form);break;
    case 'unlock-form':{if(b)b.disabled=true;const pw=new FormData(form).get('password'),p=await C.decrypt(state.locked,pw);password=pw;state.payload=p;state.locked=null;if(EDIT){config.encrypted=true;setLocal(settingKey,config);await persist();}render();break;}
  }}catch(err){formError(err);}finally{if(b)b.disabled=false;}});
  window.addEventListener('message',e=>{if(!EDIT||e.source!==window||e.data?.source!=='bangumi-import-extension')return;if(e.data.type==='QUEUE_DATA'){try{if(!$('import-results'))importDialog('extension');pending=C.parsePayload({items:e.data.items||[]}).items;pendingKind='extension';renderImportPreview();importStatus(pending.length?`插件队列有 ${pending.length} 部作品，确认后导入。`:'插件已连接，队列里暂时没有作品。');}catch(err){formError(err);}}if(e.data.type==='EXTENSION_ERROR')formError(e.data.message||'插件读取失败');});
  window.addEventListener('online',()=>toast('网络已恢复，可以刷新数据或发布修改。'));
  window.addEventListener('offline',()=>toast('已离线，修改仍会保存在本机。'));
  window.addEventListener('beforeunload',e=>{if(state.busy){e.preventDefault();e.returnValue='';}});
  try{
    document.documentElement.dataset.theme=loadJSON('hhdShelfTheme_v4',matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
    try{db=await openDB();}catch{storageFallback=true;}
    const oldConfig=loadJSON('animeWatchlistGithubConfig_v1',{});config={encrypted:false,...publicConfig(oldConfig),...boot.config,...loadJSON(settingKey,{})};
    try{ghToken=sessionStorage.getItem('hhdShelfSessionToken_v4')||'';}catch{}if(config.remember)ghToken=loadJSON('hhdShelfToken_v4','')||ghToken;
    if(EDIT){const saved=await storeGet('editor');if(saved){state.payload=C.parsePayload(saved.payload);state.dirty=!!saved.dirty;state.remoteSha=saved.remoteSha||'';state.repoKey=saved.repoKey||'';if(location.protocol!=='file:')state.notice='正在编辑本机副本。换设备编辑前，请先点右上角“刷新”读取 GitHub 最新记录。';}
      else{const legacy=loadJSON(legacyKey,null);if(Array.isArray(legacy)){state.payload=C.parsePayload(legacy);state.dirty=true;state.notice='已从此浏览器的旧追番表读取 '+legacy.length+' 条记录。建议先导出一份新版备份。';}
        else if(location.protocol!=='file:'&&!state.payload.items.length){try{const r=await fetch('./data.json?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);const raw=await r.json();if(raw.encrypted){state.locked=raw;config.encrypted=true;}else state.payload=C.parsePayload(raw);}catch(e){state.notice='暂时无法读取网页数据：'+e.message+'。可到设置中读取 GitHub，或导入备份。';}}
        if(!state.locked)await persist();}
      render();window.postMessage({source:'anime-watchlist-html',type:'HTML_READY'},'*');
    }else{render();await loadViewer();}
    if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});
  }catch(e){root.innerHTML=`<div class="locked"><h1>暂时无法打开作品库</h1><p>${esc(e.message)}</p><p>请使用新版 Chrome / Edge，或从备份重新导入。原数据不会主动删除。</p><button class="btn" onclick="location.reload()">重新加载</button></div>`;}
})();
